import{_ as e,o as t,c as a,Q as r}from"./chunks/framework.5916b37e.js";const u=JSON.parse('{"title":"Module: Controls/orbitFraming","description":"","frontmatter":{},"headers":[],"relativePath":"apidist/modules/Controls_orbitFraming.md","filePath":"apidist/modules/Controls_orbitFraming.md"}'),o={name:"apidist/modules/Controls_orbitFraming.md"},i=r('<p><a href="./../README.html">copper3d</a> / <a href="./../modules.html">Modules</a> / Controls/orbitFraming</p><h1 id="module-controls-orbitframing" tabindex="-1">Module: Controls/orbitFraming <a class="header-anchor" href="#module-controls-orbitframing" aria-label="Permalink to &quot;Module: Controls/orbitFraming&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of contents&quot;">​</a></h2><h3 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h3><ul><li><a href="./../interfaces/Controls_orbitFraming.CameraViewPreset.html">CameraViewPreset</a></li><li><a href="./../interfaces/Controls_orbitFraming.FitBounds.html">FitBounds</a></li><li><a href="./../interfaces/Controls_orbitFraming.Framing.html">Framing</a></li><li><a href="./../interfaces/Controls_orbitFraming.ViewPose.html">ViewPose</a></li></ul><h3 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;Variables&quot;">​</a></h3><ul><li><a href="./Controls_orbitFraming.html#framing_margin">FRAMING_MARGIN</a></li></ul><h3 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><ul><li><a href="./Controls_orbitFraming.html#computeframing">computeFraming</a></li><li><a href="./Controls_orbitFraming.html#fitdistance">fitDistance</a></li><li><a href="./Controls_orbitFraming.html#isrotategesture">isRotateGesture</a></li><li><a href="./Controls_orbitFraming.html#resolvefarplane">resolveFarPlane</a></li><li><a href="./Controls_orbitFraming.html#resolveviewpose">resolveViewPose</a></li></ul><h2 id="variables-1" tabindex="-1">Variables <a class="header-anchor" href="#variables-1" aria-label="Permalink to &quot;Variables&quot;">​</a></h2><h3 id="framing-margin" tabindex="-1">FRAMING_MARGIN <a class="header-anchor" href="#framing-margin" aria-label="Permalink to &quot;FRAMING\\_MARGIN&quot;">​</a></h3><p>• <code>Const</code> <strong>FRAMING_MARGIN</strong>: <code>1.3</code></p><p>Leave ~30% margin so the model does not touch the panel edge while pan/rotating.</p><h4 id="defined-in" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/467d39e/src/Controls/orbitFraming.ts#L35" target="_blank" rel="noreferrer">src/Controls/orbitFraming.ts:35</a></p><h2 id="functions-1" tabindex="-1">Functions <a class="header-anchor" href="#functions-1" aria-label="Permalink to &quot;Functions&quot;">​</a></h2><h3 id="computeframing" tabindex="-1">computeFraming <a class="header-anchor" href="#computeframing" aria-label="Permalink to &quot;computeFraming&quot;">​</a></h3><p>▸ <strong>computeFraming</strong>(<code>box</code>, <code>fovDeg</code>): <a href="./../interfaces/Controls_orbitFraming.Framing.html"><code>Framing</code></a></p><p>Bounding box -&gt; pivot + size + framing distance.</p><p>fovDeg is read from the camera by the caller at runtime (copper3d uses 75); it is not hardcoded here.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Type</th></tr></thead><tbody><tr><td style="text-align:left;"><code>box</code></td><td style="text-align:left;"><code>Box3</code></td></tr><tr><td style="text-align:left;"><code>fovDeg</code></td><td style="text-align:left;"><code>number</code></td></tr></tbody></table><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="./../interfaces/Controls_orbitFraming.Framing.html"><code>Framing</code></a></p><h4 id="defined-in-1" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in-1" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/467d39e/src/Controls/orbitFraming.ts#L66" target="_blank" rel="noreferrer">src/Controls/orbitFraming.ts:66</a></p><hr><h3 id="fitdistance" tabindex="-1">fitDistance <a class="header-anchor" href="#fitdistance" aria-label="Permalink to &quot;fitDistance&quot;">​</a></h3><p>▸ <strong>fitDistance</strong>(<code>bounds</code>, <code>aspect</code>, <code>fovDeg</code>, <code>margin?</code>): <code>number</code></p><p>How far a perspective camera must sit from an object&#39;s centre for the whole object to fit in frame.</p><p>Unlike <code>computeFraming</code> above this takes the viewport&#39;s ASPECT into account: below aspect 1 the horizontal field is the narrower of the two, and it is the narrower one that has to contain the object. A camera framed on vertical FOV alone under-frames every tall, narrow viewport.</p><p>It also fits the bounding SPHERE rather than the box. Fitting the facing box face plus half the depth frames each object by whichever dimension happens to point at the camera, so a thin slab and a near-cubic volume of similar overall extent come out at wildly different sizes on screen. A sphere has no orientation, so comparable objects get comparable screen size -- and orbiting can no longer push a corner out of frame.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Type</th><th style="text-align:left;">Default value</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>bounds</code></td><td style="text-align:left;"><a href="./../interfaces/Controls_orbitFraming.FitBounds.html"><code>FitBounds</code></a></td><td style="text-align:left;"><code>undefined</code></td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;"><code>aspect</code></td><td style="text-align:left;"><code>number</code></td><td style="text-align:left;"><code>undefined</code></td><td style="text-align:left;">Viewport width / height. Zero or non-finite is treated as 1: a viewport mid-collapse measures 0 for a frame, and NaN in a projection matrix is unrecoverable.</td></tr><tr><td style="text-align:left;"><code>fovDeg</code></td><td style="text-align:left;"><code>number</code></td><td style="text-align:left;"><code>undefined</code></td><td style="text-align:left;">The camera&#39;s VERTICAL field of view, in degrees.</td></tr><tr><td style="text-align:left;"><code>margin</code></td><td style="text-align:left;"><code>number</code></td><td style="text-align:left;"><code>0.85</code></td><td style="text-align:left;">Multiplier applied at the end, and deliberately BELOW 1. A bounding sphere circumscribes the object -- a cube&#39;s has 1.73x its half-side -- so fitting the sphere exactly leaves the object filling well under half the frame. Letting the sphere overflow is what makes the object read at a sensible size. A tuning knob, not a correctness threshold: smaller means larger on screen.</td></tr></tbody></table><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>number</code></p><h4 id="defined-in-2" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in-2" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/467d39e/src/Controls/orbitFraming.ts#L166" target="_blank" rel="noreferrer">src/Controls/orbitFraming.ts:166</a></p><hr><h3 id="isrotategesture" tabindex="-1">isRotateGesture <a class="header-anchor" href="#isrotategesture" aria-label="Permalink to &quot;isRotateGesture&quot;">​</a></h3><p>▸ <strong>isRotateGesture</strong>(<code>state</code>): <code>boolean</code></p><p>Whether this gesture is a pure rotate. Used to decide whether to snap the rotation pivot back to the model centre: OrbitControls&#39; pan moves target with the camera, so after a pan target is off the model and a rotate would orbit an empty point. We snap target back on rotate start, but must NOT on pan/dolly (or the model jumps at pan start).</p><p>Picking the wrong state constant is a silent bug (rotate not re-pivoting, or pan wrongly re-pivoting), so it is unit-tested.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Type</th></tr></thead><tbody><tr><td style="text-align:left;"><code>state</code></td><td style="text-align:left;"><code>number</code></td></tr></tbody></table><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>boolean</code></p><h4 id="defined-in-3" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in-3" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/467d39e/src/Controls/orbitFraming.ts#L53" target="_blank" rel="noreferrer">src/Controls/orbitFraming.ts:53</a></p><hr><h3 id="resolvefarplane" tabindex="-1">resolveFarPlane <a class="header-anchor" href="#resolvefarplane" aria-label="Permalink to &quot;resolveFarPlane&quot;">​</a></h3><p>▸ <strong>resolveFarPlane</strong>(<code>presetFar</code>, <code>maxDistance</code>, <code>dist</code>): <code>number</code></p><p>Far clipping plane (decision D2).</p><p>The preset&#39;s farPlane is 1000, but a large volume&#39;s maxDistance (= size*5) can exceed it, which would clip the model when the user zooms all the way out.</p><p>The Number.isFinite guard is required: right after construction and before the first frameBox, OrbitControls&#39; maxDistance is still the default Infinity.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Type</th></tr></thead><tbody><tr><td style="text-align:left;"><code>presetFar</code></td><td style="text-align:left;"><code>number</code></td></tr><tr><td style="text-align:left;"><code>maxDistance</code></td><td style="text-align:left;"><code>number</code></td></tr><tr><td style="text-align:left;"><code>dist</code></td><td style="text-align:left;"><code>number</code></td></tr></tbody></table><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>number</code></p><h4 id="defined-in-4" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in-4" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/467d39e/src/Controls/orbitFraming.ts#L114" target="_blank" rel="noreferrer">src/Controls/orbitFraming.ts:114</a></p><hr><h3 id="resolveviewpose" tabindex="-1">resolveViewPose <a class="header-anchor" href="#resolveviewpose" aria-label="Permalink to &quot;resolveViewPose&quot;">​</a></h3><p>▸ <strong>resolveViewPose</strong>(<code>preset</code>, <code>pivot</code>, <code>dist</code>): <a href="./../interfaces/Controls_orbitFraming.ViewPose.html"><code>ViewPose</code></a></p><p>Preset + pivot + distance -&gt; camera pose.</p><p>The preset&#39;s eyePosition is absolute; only its DIRECTION is taken here, and the distance comes from C5 auto-framing (the implicit 600 in the JSON is ignored).</p><p>up must be Gram-Schmidt-orthogonalised against the view direction (decision D1): OrbitControls uses camera.up as its polar axis, and nrrd_view_coronal.json&#39;s up (0,1,-1) is not perpendicular to its own view direction (0,1,0) — feeding it raw gives a 45-degree-tilted pole. The old trackball path got away with it only because three&#39;s lookAt() orthogonalises internally.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Type</th></tr></thead><tbody><tr><td style="text-align:left;"><code>preset</code></td><td style="text-align:left;"><a href="./../interfaces/Controls_orbitFraming.CameraViewPreset.html"><code>CameraViewPreset</code></a></td></tr><tr><td style="text-align:left;"><code>pivot</code></td><td style="text-align:left;"><code>Vector3</code></td></tr><tr><td style="text-align:left;"><code>dist</code></td><td style="text-align:left;"><code>number</code></td></tr></tbody></table><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="./../interfaces/Controls_orbitFraming.ViewPose.html"><code>ViewPose</code></a></p><h4 id="defined-in-5" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in-5" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/467d39e/src/Controls/orbitFraming.ts#L86" target="_blank" rel="noreferrer">src/Controls/orbitFraming.ts:86</a></p>',73),n=[i];function l(s,d,c,h,m,f){return t(),a("div",null,n)}const p=e(o,[["render",l]]);export{u as __pageData,p as default};
